using System.Drawing;using System.Drawing.Drawing2D;
namespace EanEtikety { public static class BrandLogo {
 public static Bitmap Image(int size){var b=new Bitmap(size,size);using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(size/128f,size/128f);using(var path=new GraphicsPath()){path.AddArc(0,0,56,56,180,90);path.AddArc(72,0,56,56,270,90);path.AddArc(72,72,56,56,0,90);path.AddArc(0,72,56,56,90,90);path.CloseFigure();using(var brush=new SolidBrush(StudioTheme.Accent))g.FillPath(brush,path);}using(var pen=new Pen(Color.White,size<=24?7:6){LineJoin=LineJoin.Round}){g.DrawPolygon(pen,new[]{new PointF(29,29),new PointF(78,29),new PointF(100,51),new PointF(100,99),new PointF(29,99)});g.DrawLines(pen,new[]{new PointF(78,29),new PointF(78,51),new PointF(100,51)});}using(var pen=new Pen(Color.White,size<=24?6:5){LineJoin=LineJoin.Round,StartCap=LineCap.Square,EndCap=LineCap.Square}){g.DrawLines(pen,new[]{new PointF(42,84),new PointF(42,59),new PointF(59,84),new PointF(59,59)});using(var path=new GraphicsPath()){path.AddLines(new[]{new PointF(71,59),new PointF(71,84),new PointF(78,84)});path.AddBezier(78,84,94,84,94,59,78,59);path.CloseFigure();g.DrawPath(pen,path);}}}return b;}
}}
